            # Replace comma with dot for parsing
            val = val.replace(',', '.')
            return float(val)
        else:
            return float(val)

    val_a = parse_value(a)
    val_b = parse_value(b)

    if val_a > val_b:
        return a
    elif val_b > val_a:
        return b
    else:
        return None
